export function formatDuration(minutes) {
  if (!Number.isInteger(minutes) || minutes < 0) throw new RangeError('nonnegative integer required');
  if (!minutes) return '';
  return `${minutes} min`;
}

export function slug(text) {
  return text.trim().toLowerCase().replaceAll(' ', '-');
}

import {test} from 'node:test';
import assert from 'node:assert/strict';
import {formatDuration} from '../src/format-duration.mjs';
test('zero minutes has an explicit label', () => assert.equal(formatDuration(0), '0 min'));
test('positive durations retain their labels', () => { assert.equal(formatDuration(1), '1 min'); assert.equal(formatDuration(60), '60 min'); });
test('invalid durations still reject', () => { assert.throws(() => formatDuration(-1), RangeError); assert.throws(() => formatDuration(1.5), RangeError); });

import {test} from 'node:test';
import assert from 'node:assert/strict';
import {slug} from '../src/slug.mjs';
test('unrelated slug behavior stays unchanged', () => assert.equal(slug('  A B  '), 'a-b'));

